const DEMO_EMAIL = 'demo@tumblez.finance';
const DEMO_PIN = '1234';
const DEMO_SALT = 'tumblez-demo-salt-v1';
const encoder = new TextEncoder();

const conceptAssets = [
  ['cash-concept-1','cash','asset','เงินสำรองฉุกเฉิน','บัญชีสภาพคล่องหลัก',180000,'เป้าหมาย 6 เดือนของค่าใช้จ่าย'], ['cash-concept-2','cash','asset','บัญชีใช้จ่ายประจำวัน','บัญชีธนาคารหลัก',42000,'ยอดสำหรับหมุนเวียน'], ['investment-concept-1','investment','asset','กองทุนระยะยาว','พอร์ตลงทุน A',420000,'ติดตามผลตอบแทนรายเดือน'], ['investment-concept-2','investment','asset','พอร์ตกระจายความเสี่ยง','พอร์ตลงทุน B',160000,'สัดส่วนหุ้นและตราสารหนี้'], ['personal-concept-1','personal','asset','ที่อยู่อาศัย','เอกสารทรัพย์สิน',2800000,'มูลค่าประเมินล่าสุด'], ['personal-concept-2','personal','asset','ยานพาหนะ','เอกสารทรัพย์สิน',520000,'มูลค่าประเมินปัจจุบัน'], ['debt-concept-1','debt','liability','สินเชื่อที่อยู่อาศัย','สัญญาสินเชื่อ A',1650000,'ทบทวนยอดคงเหลือทุกเดือน'], ['debt-concept-2','debt','liability','สินเชื่อยานพาหนะ','สัญญาสินเชื่อ B',210000,'เหลือระยะเวลาผ่อนตามสัญญา']
];
const conceptCards = [
  ['card-concept-primary','Primary Bank','Everyday Card','1284','2028-12',15,5,100000,'ink','/assets/banks/primary-bank.svg'], ['card-concept-travel','Travel Bank','Travel Rewards','5702','2029-06',22,7,150000,'violet','/assets/banks/travel-bank.svg'], ['card-concept-digital','Digital Bank','Digital Flex','9341','2027-10',28,13,70000,'teal','/assets/banks/digital-bank.svg']
];
const conceptItems = [
  ['item-concept-work','อุปกรณ์ทำงาน','WORK EQUIPMENT','Gadget','card-concept-primary',36000,0,10,3], ['item-concept-home','เครื่องใช้ในบ้าน','HOME LIVING','เครื่องใช้ไฟฟ้า','card-concept-digital',8400,0,6,2], ['item-concept-trip','ทริปพักผ่อนประจำปี','ANNUAL TRIP','ท่องเที่ยว','card-concept-travel',24000,600,12,4], ['item-concept-health','แพ็กเกจสุขภาพ','HEALTH PLAN','สุขภาพ','card-concept-primary',12000,0,6,6]
];

function hex(bytes) { return [...new Uint8Array(bytes)].map(byte => byte.toString(16).padStart(2,'0')).join(''); }
function base64url(value) { return btoa(String.fromCharCode(...new Uint8Array(value))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
function fromBase64url(value) { const padded = value.replace(/-/g,'+').replace(/_/g,'/') + '='.repeat((4 - value.length % 4) % 4); return Uint8Array.from(atob(padded), char => char.charCodeAt(0)); }
async function hashPin(pin, salt) { const key = await crypto.subtle.importKey('raw', encoder.encode(pin), 'PBKDF2', false, ['deriveBits']); const bits = await crypto.subtle.deriveBits({ name:'PBKDF2', salt:encoder.encode(salt), iterations:120000, hash:'SHA-256' }, key, 256); return hex(bits); }
async function signToken(userId, secret) { const payload = base64url(encoder.encode(JSON.stringify({ userId, exp:Date.now() + 1000 * 60 * 60 * 12 }))); const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name:'HMAC', hash:'SHA-256' }, false, ['sign']); const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(payload)); return `${payload}.${base64url(signature)}`; }
async function verifyToken(token, secret) { try { const [payload, signature] = token.split('.'); if (!payload || !signature) return null; const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name:'HMAC', hash:'SHA-256' }, false, ['verify']); if (!await crypto.subtle.verify('HMAC', key, fromBase64url(signature), encoder.encode(payload))) return null; const parsed = JSON.parse(new TextDecoder().decode(fromBase64url(payload))); return parsed.exp > Date.now() ? Number(parsed.userId) : null; } catch { return null; } }
async function jsonBody(request) { try { return await request.json(); } catch { throw new Error('invalid json'); } }
function json(data, status = 200) { return new Response(JSON.stringify(data), { status, headers:{ 'content-type':'application/json; charset=utf-8', 'cache-control':'no-store' } }); }
async function authUser(request, env) { const header = request.headers.get('authorization') || ''; const token = header.startsWith('Bearer ') ? header.slice(7) : ''; return token ? verifyToken(token, env.SESSION_SECRET || 'change-me-before-production') : null; }
async function ensureSeed(env) { const found = await env.DB.prepare('SELECT id FROM users WHERE email = ? LIMIT 1').bind(DEMO_EMAIL).first(); if (found) return; const statements = [env.DB.prepare('INSERT INTO users (id,email,pin_salt,pin_hash) VALUES (?,?,?,?)').bind(1, DEMO_EMAIL, DEMO_SALT, await hashPin(DEMO_PIN, DEMO_SALT))]; conceptAssets.forEach(row => statements.push(env.DB.prepare('INSERT INTO assets (id,user_id,category,kind,name,account,value,notes) VALUES (?,?,?,?,?,?,?,?)').bind(row[0],1,...row.slice(1)))); conceptCards.forEach(row => statements.push(env.DB.prepare('INSERT INTO cards (id,user_id,bank,name,last_four,expiry,statement_day,due_day,credit_limit,tone,logo) VALUES (?,?,?,?,?,?,?,?,?,?,?)').bind(row[0],1,...row.slice(1)))); conceptItems.forEach(row => statements.push(env.DB.prepare('INSERT INTO installments (id,user_id,name,statement_name,category,card_id,total_price,interest,total_installments,paid_installments) VALUES (?,?,?,?,?,?,?,?,?,?)').bind(row[0],1,...row.slice(1)))); await env.DB.batch(statements); }
async function rowsFor(env, userId) { const [assets, cards, items] = await Promise.all([env.DB.prepare('SELECT id,category,kind,name,account,value,notes FROM assets WHERE user_id = ? ORDER BY rowid').bind(userId).all(), env.DB.prepare('SELECT id,bank,name,last_four AS lastFour,expiry,statement_day AS statementDay,due_day AS dueDay,credit_limit AS "limit",tone,logo FROM cards WHERE user_id = ? ORDER BY rowid').bind(userId).all(), env.DB.prepare('SELECT id,name,statement_name AS statementName,category,card_id AS cardId,total_price AS totalPrice,interest,total_installments AS totalInstallments,paid_installments AS paidInstallments FROM installments WHERE user_id = ? ORDER BY rowid').bind(userId).all()]); return { assets:assets.results || [], cards:cards.results || [], items:items.results || [] }; }

async function handleApi(request, env) {
  const url = new URL(request.url);
  if (request.method === 'GET' && url.pathname === '/api/health') return json({ status:'ok', database:'cloudflare-d1' });
  if (request.method === 'POST' && url.pathname === '/api/auth/login') { try { await ensureSeed(env); const body = await jsonBody(request); const email = String(body.email || '').trim().toLowerCase(); const pin = String(body.pin || ''); const user = await env.DB.prepare('SELECT id,email,pin_salt,pin_hash FROM users WHERE email = ?').bind(email).first(); const hash = user ? await hashPin(pin, user.pin_salt) : ''; if (!user || hash !== user.pin_hash) return json({ error:'อีเมลหรือ PIN ไม่ถูกต้อง' }, 401); return json({ token:await signToken(Number(user.id), env.SESSION_SECRET || 'change-me-before-production'), user:{ id:Number(user.id), email:user.email } }); } catch (error) { return json({ error:error.message }, 400); } }
  if (request.method === 'POST' && url.pathname === '/api/auth/logout') return json({ status:'signed_out' });
  const userId = await authUser(request, env); if (!userId) return json({ error:'กรุณาเข้าสู่ระบบ' }, 401);
  if (request.method === 'GET' && url.pathname === '/api/me') { const user = await env.DB.prepare('SELECT id,email FROM users WHERE id = ?').bind(userId).first(); return user ? json({ user:{ id:Number(user.id), email:user.email } }) : json({ error:'ไม่พบบัญชี' }, 404); }
  if (request.method === 'GET' && url.pathname === '/api/finance') return json(await rowsFor(env, userId));
  if (request.method === 'PUT' && url.pathname === '/api/finance') { try { const body = await jsonBody(request); const assets = Array.isArray(body.assets) ? body.assets : []; const cards = Array.isArray(body.cards) ? body.cards : []; const items = Array.isArray(body.items) ? body.items : []; const statements = [env.DB.prepare('DELETE FROM installments WHERE user_id = ?').bind(userId), env.DB.prepare('DELETE FROM assets WHERE user_id = ?').bind(userId), env.DB.prepare('DELETE FROM cards WHERE user_id = ?').bind(userId)]; assets.forEach(r => statements.push(env.DB.prepare('INSERT INTO assets (id,user_id,category,kind,name,account,value,notes) VALUES (?,?,?,?,?,?,?,?)').bind(String(r.id),userId,String(r.category || 'cash'),String(r.kind || 'asset'),String(r.name || ''),String(r.account || ''),Number(r.value) || 0,String(r.notes || '')))); cards.forEach(c => statements.push(env.DB.prepare('INSERT INTO cards (id,user_id,bank,name,last_four,expiry,statement_day,due_day,credit_limit,tone,logo) VALUES (?,?,?,?,?,?,?,?,?,?,?)').bind(String(c.id),userId,String(c.bank || ''),String(c.name || ''),String(c.lastFour || ''),String(c.expiry || ''),Number(c.statementDay) || null,Number(c.dueDay) || null,Number(c.limit) || 0,String(c.tone || 'ink'),String(c.logo || '')))); items.forEach(i => statements.push(env.DB.prepare('INSERT INTO installments (id,user_id,name,statement_name,category,card_id,total_price,interest,total_installments,paid_installments) VALUES (?,?,?,?,?,?,?,?,?,?)').bind(String(i.id),userId,String(i.name || ''),String(i.statementName || ''),String(i.category || 'อื่น ๆ'),String(i.cardId || ''),Number(i.totalPrice) || 0,Number(i.interest) || 0,Math.max(1,Number(i.totalInstallments) || 1),Math.max(0,Number(i.paidInstallments) || 0)))); await env.DB.batch(statements); return json({ status:'saved', ...(await rowsFor(env,userId)) }); } catch (error) { return json({ error:error.message }, 400); } }
  return json({ error:'not found' }, 404);
}

export default { async fetch(request, env) { const url = new URL(request.url); if (url.pathname.startsWith('/api/')) return handleApi(request, env); return env.ASSETS.fetch(request); } };

